use maho_ext_pi_rules::{rules::types::{MatchReason,RuleDiagnostic,Severity},ui::rules_banner::*};
use maho_interactive::theme::{ColorMode,Theme,ThemeColor,theme_json::{ColorValue,ThemeJson}};
fn theme()->Theme{Theme::from_json(ThemeJson{name:"fixture".into(),vars:Default::default(),colors:[("border",8),("accent",6),("muted",7),("error",1),("success",2),("warning",3)].into_iter().map(|(key,value)|(key.into(),ColorValue::Index(value))).collect(),export_colors:Default::default()},ColorMode::Truecolor).expect("theme")}
#[test]fn empty_banner_borders_follow_width(){let theme=theme();let props=RulesBannerProps{rule_count:0,diagnostics:Vec::new(),top_rules:None};let lines=render_banner_lines(&props,&theme,0);assert_eq!(lines.len(),3);assert_eq!(lines[0],theme.fg(ThemeColor::Border,"\u{2500}"));assert_eq!(lines[0],lines[2]);}
#[test]fn rule_diagnostics_match_absolute_or_relative_path(){let theme=theme();for source in ["rules.md","/fixture/rules.md"]{let props=RulesBannerProps{rule_count:1,diagnostics:vec![RuleDiagnostic{severity:Severity::Warning,source:source.into(),message:String::new()}],top_rules:Some(vec![BannerRule{relative_path:"rules.md".into(),path:Some("/fixture/rules.md".into()),match_reason:MatchReason::Glob{pattern:"src/**".into()}}])};let lines=render_banner_lines(&props,&theme,40);assert!(lines[3].contains(&theme.fg(ThemeColor::Error,"\u{26a0}")));assert!(lines[3].ends_with(&theme.fg(ThemeColor::Muted,"src/**")));}}
#[test]fn unmatched_rule_uses_success_indicator(){let theme=theme();let props=RulesBannerProps{rule_count:1,diagnostics:Vec::new(),top_rules:Some(vec![BannerRule{relative_path:"rules.md".into(),path:None,match_reason:MatchReason::SingleFile}])};let lines=render_banner_lines(&props,&theme,40);assert!(lines[3].contains(&theme.fg(ThemeColor::Success,"\u{25cf}")));assert_eq!(lines.len(),6);}
